import type { IBaseMessageResponse, IBaseServerResponse } from '@game-studio/arcade-base';

export interface IServerResponse extends IBaseServerResponse {
    GameMessage: IGameMessageResponse;
}

export interface IGameMessageResponse extends IBaseMessageResponse {
    ArcadeGameType: string;
    Payout: number;
    Winner: boolean;
    BonusRound?: IBonusRound;
    Game: IGame;
}

export interface IReelPosition {
    Reel: number;
    Row: number;
}

export interface IGame {
    GameResult: IGameResult;
    BonusRound?: IBonusRound;
}

export interface IGameResult {
    Bonus: boolean;
    CascadeCount: number;
    Outcomes: IOutcome[];
    ScatterResult?: IScatterResult;
    SplitSymbolDetails: ISplitSymbolDetail[];
}

export interface IOutcome {
    DisplayReels: number[][];
    Prize: number;
    Results: IOutcomeResult[];
    SplitSymbols: ISplitSymbol[];
    Stops: number[];
    WinWays: number;
}

export interface IOutcomeResult {
    Positions: IReelPosition[];
    OutcomeType: string;
    Matched: number;
    Symbol: number;
    Prize: number;
    Wild: boolean;
    IsSplit: boolean;
    SymbolMultiplier: number;
    SplitMultiplier: number;
    TotalMultiplier: number;
}

export interface ISplitSymbolDetail {
    HighlightedPosition: ISplitSymbol[];
    Split: number;
    Symbol: number;
}

export interface ISplitSymbol {
    Reel: number;
    Row: number;
}

export interface IPrizeResult {
    Prize: number;
    Positions: IReelPosition[];
    Symbol: number;
    Matched: number;
    Multiplier: number;
    OutcomeType: string;
    Wild: boolean;
}

export interface IScatterResult {
    Bonus: boolean;
    Count: number;
    Multiplier: number;
    OutcomeType: string;
    Positions: IReelPosition[];
    Prize: number;
    Symbol: number;
}

export interface IBonusRound extends IGameResult {
    BonusPayout: number;
    TotalBonusPayout: number;
    Number: number;
    Remaining: number;
}
